#define ASCENDC_CHECK(x)  \
    do {                  \
        if (!(x)) {       \
            return false; \
        }                 \
    } while (0)

#define ASCENDC_CHECK_AND_LOG(cond, behavior) \
    do {                                      \
        if (!(cond)) {                        \
            behavior;                         \
            return false;                     \
        }                                     \
    } while (0)

#define ASCENDC_MODULE_NAME static_cast<int32_t>(ASCENDCKERNEL)

